auto begin=window->from,end=window->to;auto a0=road_progress_at(*a,begin,b),a1=road_progress_at(*a,end,b),c0=road_progress_at(*c,begin,b),c1=road_progress_at(*c,end,b);auto la=integer(ae->duration_ticks*100,b),lc=integer(ce->duration_ticks*100,b);auto normal=[&](const CanonicalFraction& x,const CanonicalFraction& length,bool forward){return div(forward?x:sub(length,x,b),length,b);};auto na0=normal(a0,la,ae->origin<ae->destination),na1=normal(a1,la,ae->origin<ae->destination),nc0=normal(c0,lc,ce->origin<ce->destination),nc1=normal(c1,lc,ce->origin<ce->destination);int start_sign=compare(na0,nc0,b),end_sign=compare(na1,nc1,b);if((start_sign==0&&end_sign==0)||(start_sign!=0&&end_sign!=0&&start_sign==end_sign))return {};auto gap0=start_sign>=0?sub(na0,nc0,b):sub(nc0,na0,b),gap1=end_sign>=0?sub(na1,nc1,b):sub(nc1,na1,b);auto u=div(gap0,add(gap0,gap1,b),b);auto pa=take(floor_fraction(lerp_progress(a0,a1,u,b),b)),pc=take(floor_fraction(lerp_progress(c0,c1,u,b),b));if(pa<=0||pa>=ae->duration_ticks*100||pc<=0||pc>=ce->duration_ticks*100)return {};
auto trace=[&](const MovementPrefixState& p,const RoadMovementBasis& basis,const CanonicalFraction& from,const CanonicalFraction& to){auto out=basis.original_inputs;const auto* unit=state.units.find(p.unit_ref);const auto* effort=unit&&unit->effort_basis_refs.size()>0?state.exertion_bases.find(unit->effort_basis_refs.back().id):nullptr;if(!effort)fail("ContactParticipantBasisRequired",p.id);out.actor_id=effort->original_action?effort->original_action->actor_id:spatial_carrier_key(std::get<GroupMovementExecution>(p.execution).carrier);out.action_id=effort->original_action?effort->original_action->id:execution_key(p.execution);out.start=take(floor_fraction(from,b));out.end=take(floor_fraction(to,b));out.moving=compare(from,to,b)!=0;return out;};auto at=trace(*a,*ab,a0,a1),ct=trace(*c,*cb,c0,c1);if(!at.params.encounter_id.empty()||!ct.params.encounter_id.empty()||std::find(at.params.met_actions.begin(),at.params.met_actions.end(),ct.action_id)!=at.params.met_actions.end()||std::find(ct.params.met_actions.begin(),ct.params.met_actions.end(),at.action_id)!=ct.params.met_actions.end())return {};
const auto* am=std::get_if<RunningMovementMap>(&a->activity_world_map);const auto* cm=std::get_if<RunningMovementMap>(&c->activity_world_map);const bool original=am&&cm&&!ab->continued&&!cb->continued&&same_moment(am->world_from,cm->world_from,b)&&compare(am->cursor_at_from,{},b)==0&&compare(cm->cursor_at_from,{},b)==0&&compare(am->rate,integer(1,b),b)==0&&compare(cm->rate,integer(1,b),b)==0&&compare(take(elapsed_world_duration(begin,end,b)).value,integer(1,b),b)==0;
if(original){auto hit=original_road_contact_intersection(catalog,at,ct);if(!hit)return {};auto mapped=take(map_movement_contact("prediction",*hit,begin,take(elapsed_world_duration(begin,end,b)),first,second,b));mapped.id.clear();if(take(compare_world_moments(mapped.occurred_at,current,b))<0)fail("UnsettledPastMovementContact",first);return mapped;}
